/**
 * Build-time tool: re-encodes the scene art from assets/images-src/*.png
 * into right-sized WebP in public/images/. Never imported by the app.
 *
 *   npm run optimize-images
 *
 * assets/images-src/ is the editable source of truth: full-resolution PNG,
 * the only thing an art change should ever touch. Everything under
 * public/images/ is generated by this script and safe to delete.
 *
 * The sources sit outside public/ on purpose. Vite copies publicDir into the
 * build verbatim, so sources kept there would ship ~7 MB of PNG to the CDN
 * and be publicly fetchable. (.assetsignore does not save you: wrangler feeds
 * recursive readdir output straight to a gitignore matcher without
 * normalizing separators, so on Windows `images\\src\\desk.png` never matches
 * an `images/src/` pattern.)
 *
 * Each layer's target width comes from the composition rather than a global
 * constant: box.width * SCENE_MAX_WIDTH is the widest that layer is ever
 * rendered, and DEVICE_PIXEL_RATIO doubles it for retina. A source is never
 * upscaled past its native width, so the target is a ceiling, not a demand.
 */

import type { Buffer } from "node:buffer";
import { readFileSync, statSync } from "node:fs";
import process from "node:process";
import { fileURLToPath } from "node:url";
import sharp from "sharp";
import {
	SCENE_LAYERS,
	SCENE_MAX_WIDTH,
	SCENE_MOBILE_IMAGE,
} from "../src/config/scene";

/** Matches the browser default; SCENE_MAX_WIDTH is authored in rem. */
const ROOT_FONT_SIZE = 16;
const DEVICE_PIXEL_RATIO = 2;

/**
 * The resize does nearly all the work here (98% of the saving), so quality
 * is set by where the art stops improving, not by the byte budget: totals
 * across the eight layers run 122 KB at q80, 168 at q90, 224 at q95, all
 * of them far under the 500 KB ceiling. 90 is the knee — it buys back the
 * chalk texture and paper grain that q80 blocks, and the next five points
 * cost 56 KB for nothing the eye finds. alphaQuality stays higher still:
 * every asset is a cutout, and a soft alpha edge is what sells it against
 * the cream field.
 */
const WEBP_QUALITY = 90;
const WEBP_ALPHA_QUALITY = 90;
/** 0..6, encode time only. This runs by hand, so take the slowest. */
const WEBP_EFFORT = 6;

/**
 * The flat mobile image is not a layer, so it has no box to size it. Below
 * md the scene box is the viewport minus the page's px-4 gutters, and the
 * breakpoint itself caps the viewport.
 */
const MOBILE_MAX_WIDTH = 768 - 32;

const srcDir = fileURLToPath(new URL("../assets/images-src/", import.meta.url));
const outDir = fileURLToPath(new URL("../public/images/", import.meta.url));

/** SCENE_MAX_WIDTH is a CSS length, not a number; resolve it to pixels. */
function cssLengthToPixels(value: string): number {
	const match = /^\s*([\d.]+)(rem|px)\s*$/.exec(value);
	if (!match) {
		throw new Error(
			`SCENE_MAX_WIDTH is "${value}"; this script only resolves rem and px.`,
		);
	}
	return match[2] === "rem" ? Number(match[1]) * ROOT_FONT_SIZE : Number(match[1]);
}

/** "/images/desk.webp" -> "desk". */
function baseName(imagePath: string): string {
	return (imagePath.split("/").pop() ?? "").replace(/\.[^.]+$/, "");
}

function formatKilobytes(bytes: number): string {
	return `${(bytes / 1024).toFixed(1)} KB`;
}

interface Result {
	id: string;
	sourceWidth: number;
	outputWidth: number;
	beforeBytes: number;
	afterBytes: number;
}

const sceneMaxWidthPx = cssLengthToPixels(SCENE_MAX_WIDTH);

/**
 * The mobile image is a full-bleed cover, so it has no layer box; it joins
 * the same list as a synthetic entry rather than getting a second code path.
 */
const targets = [
	...SCENE_LAYERS.map((layer) => ({
		id: layer.id,
		image: layer.image,
		targetWidth: Math.round(
			layer.box.width * sceneMaxWidthPx * DEVICE_PIXEL_RATIO,
		),
	})),
	{
		id: "scene-flat-mobile",
		image: SCENE_MOBILE_IMAGE,
		targetWidth: MOBILE_MAX_WIDTH * DEVICE_PIXEL_RATIO,
	},
];

const results: Result[] = [];
const skipped: string[] = [];

for (const target of targets) {
	const name = baseName(target.image);
	let source: Buffer;
	try {
		source = readFileSync(`${srcDir}${name}.png`);
	} catch {
		skipped.push(`${target.id}: no source at assets/images-src/${name}.png`);
		continue;
	}

	const { width: sourceWidth } = await sharp(source).metadata();
	if (sourceWidth === undefined) {
		throw new Error(`${name}.png has no decodable width`);
	}
	// withoutEnlargement below would also cover this, but resolving the
	// width up front is what lets the printed table be honest about which
	// assets were already smaller than their target.
	const outputWidth = Math.min(target.targetWidth, sourceWidth);
	const outputPath = `${outDir}${name}.webp`;

	await sharp(source)
		.resize({ width: outputWidth, withoutEnlargement: true })
		.webp({
			quality: WEBP_QUALITY,
			alphaQuality: WEBP_ALPHA_QUALITY,
			effort: WEBP_EFFORT,
		})
		.toFile(outputPath);

	results.push({
		id: target.id,
		sourceWidth,
		outputWidth,
		beforeBytes: source.length,
		afterBytes: statSync(outputPath).size,
	});
}

// A scene missing its art is broken, not degraded: fail loudly rather than
// print an empty table that reads like a successful run.
if (results.length === 0) {
	console.error("No sources found in assets/images-src/ — nothing written.");
	process.exit(1);
}

const columns = [
	{ heading: "layer", value: (r: Result) => r.id },
	{
		heading: "px",
		value: (r: Result) => `${r.sourceWidth} -> ${r.outputWidth}`,
	},
	{ heading: "before", value: (r: Result) => formatKilobytes(r.beforeBytes) },
	{ heading: "after", value: (r: Result) => formatKilobytes(r.afterBytes) },
	{
		heading: "saved",
		value: (r: Result) =>
			`${(100 - (100 * r.afterBytes) / r.beforeBytes).toFixed(1)}%`,
	},
];

const totalBefore = results.reduce((sum, r) => sum + r.beforeBytes, 0);
const totalAfter = results.reduce((sum, r) => sum + r.afterBytes, 0);
const rows = results.map((result) =>
	columns.map((column) => column.value(result)),
);
const total = [
	"TOTAL",
	"",
	formatKilobytes(totalBefore),
	formatKilobytes(totalAfter),
	`${(100 - (100 * totalAfter) / totalBefore).toFixed(1)}%`,
];

const widths = columns.map((column, index) =>
	Math.max(
		column.heading.length,
		...[...rows, total].map((row) => row[index].length),
	),
);
const line = (cells: string[]) =>
	cells
		.map((cell, index) => cell.padEnd(widths[index]))
		.join("  ")
		.trimEnd();
const rule = widths.map((width) => "-".repeat(width)).join("  ");

console.log(line(columns.map((column) => column.heading)));
console.log(rule);
for (const row of rows) {
	console.log(line(row));
}
console.log(rule);
console.log(line(total));

for (const message of skipped) {
	console.log(`skipped ${message}`);
}
